const catalogFilterLabels:Record<CatalogFilterKey,string>={bodyPart:'Body part',target:'Target muscle',primaryMuscles:'Primary muscles',secondaryMuscles:'Secondary muscles',equipment:'Equipment',apparatus:'Apparatus',difficulty:'Difficulty',type:'Type',category:'Category',mechanic:'Mechanic',force:'Force',tags:'Tags'};
